{'CARDS': '      <article class="award-card">\n        <div class="award-image"><img src="/assets/ring-1.webp" alt="Carnelian Seal" loading="lazy"></div>\n        <h3 class="award-name">Carnelian Seal</h3>\n        <p class="award-price">$480</p>\n      </article>\n      <article class="award-card">\n        <div class="award-image"><img src="/assets/ring-2.webp" alt="Moonstone Dome" loading="lazy"></div>\n        <h3 class="award-name">Moonstone Dome</h3>\n        <p class="award-price">$560</p>\n      </article>\n      <article class="award-card">\n        <div class="award-image"><img src="/assets/ring-3.webp" alt="Hammered Disc" loading="lazy"></div>\n        <h3 class="award-name">Hammered Disc</h3>\n        <p class="award-price">$620</p>\n      </article>\n      <article class="award-card">\n        <div class="award-image"><img src="/assets/ring-4.webp" alt="Quadrant Band" loading="lazy"></div>\n        <h3 class="award-name">Quadrant Band</h3>\n        <p class="award-price">$740</p>\n      </article>\n      <article class="award-card">\n        <div class="award-image"><img src="/assets/ring-1.webp" alt="Pale Signet" loading="lazy"></div>\n        <h3 class="award-name">Pale Signet</h3>\n        <p class="award-price">$820</p>\n      </article>\n      <article class="award-card">\n        <div class="award-image"><img src="/assets/ring-2.webp" alt="Twin Dome" loading="lazy"></div>\n        <h3 class="award-name">Twin Dome</h3>\n        <p class="award-price">$950</p>\n      </article>', 'STATS': '      <div class="stat-card">\n        <div class="stomp-wrapper">\n          <div class="stomp-stack stack-a"><h1 class="heading-style-h1">100%</h1><h1 class="heading-style-h1">100%</h1></div>\n          <div class="stomp-stack stack-b"><h1 class="heading-style-h1">Handmade</h1><h1 class="heading-style-h1">Handmade</h1></div>\n        </div>\n        <p class="detail-paragraph">Every ring cut, forged and finished by one pair of hands</p>\n      </div>\n      <div class="stat-card">\n        <div class="stomp-wrapper">\n          <div class="stomp-stack stack-a"><h1 class="heading-style-h1">14-92g</h1><h1 class="heading-style-h1">14-92g</h1></div>\n          <div class="stomp-stack stack-b"><h1 class="heading-style-h1">Per piece</h1><h1 class="heading-style-h1">Per piece</h1></div>\n        </div>\n        <p class="detail-paragraph">Weight is chosen, not left over — you feel each ring on the hand</p>\n      </div>\n      <div class="stat-card">\n        <div class="stomp-wrapper">\n          <div class="stomp-stack stack-a"><h1 class="heading-style-h1">Sterling</h1><h1 class="heading-style-h1">Sterling</h1></div>\n          <div class="stomp-stack stack-b"><h1 class="heading-style-h1">& Stone</h1><h1 class="heading-style-h1">& Stone</h1></div>\n        </div>\n        <p class="detail-paragraph">Solid silver and set stone only — no plating, no filler</p>\n      </div>\n      <div class="stat-card">\n        <div class="stomp-wrapper">\n          <div class="stomp-stack stack-a"><h1 class="heading-style-h1">Lifetime</h1><h1 class="heading-style-h1">Lifetime</h1></div>\n          <div class="stomp-stack stack-b"><h1 class="heading-style-h1">Guarantee</h1><h1 class="heading-style-h1">Guarantee</h1></div>\n        </div>\n        <p class="detail-paragraph">Bring it back in twenty years and we will make it right</p>\n        <p class="card-subtext">Est. ANULA Studio, 2021.</p>\n      </div>', 'PARAS': '        <p class="left-para" data-fade-slide-in>Each ring is made by one person from start to finish — no line, no batch, no shortcut. The stone is chosen first and the silver is shaped to hold it.</p>\n        <p class="left-para" data-fade-slide-in>We work in solid sterling and set stone. Nothing is plated, nothing is hollowed. The weight you feel is the metal itself.</p>\n        <p class="left-para" data-fade-slide-in>ANULA is for people who want one good thing rather than several forgettable ones. Made slowly, worn for decades.</p>', 'DISCOVER': '<button class="capsule-btn js-to-footer" type="button"><span>Discover</span><span class="capsule-circle"></span></button>', 'VIEWCOL': '<button class="capsule-btn " type="button"><span>View collection</span><span class="capsule-circle"></span></button>'}